// reg - TargetTransactionInterfaceRegisters_rx_desc_fifo_size_5_tx_desc_fifo_size_5_rx_fifo_size_5_tx_fifo_size_5_ibi_fifo_size_5::INTERRUPT_STATUS
// Interrupt Status.
// How a bit is cleared depends on the bit:
// - Auto-cleared by hardware on a specific access: RX_DESC_STAT, RX_DESC_THLD_STAT
// and RX_DATA_THLD_STAT clear when software reads the corresponding RX queue; IBI_DONE
// clears when software reads STATUS.LAST_IBI_STATUS. These bits are also write-1-to-clear,
// but the normal servicing access clears them without an explicit write here.
// - Write-1-to-clear only (no hardware auto-clear): TX_DESC_COMPLETE, TX_DESC_STAT,
// TX_DESC_THLD_STAT, TX_DATA_THLD_STAT, IBI_THLD_STAT, and the not-implemented
// TRANSFER_ERR_STAT, TRANSFER_ABORT_STAT, TX_DESC_TIMEOUT, RX_DESC_TIMEOUT. Write 1 to
// the bit in this register to clear it.
// - Read-only, hardware-driven level status that cannot be cleared by software:
// PENDING_IBI and PENDING_INTERRUPT track live conditions.
// There is a pending Write Transaction. Software should read data from the RX Descriptor Queue and the RX Data Queue. Clear: auto-cleared by hardware when software reads the RX Descriptor Queue; writing 1 to this bit in INTERRUPT_STATUS also clears it.
#define TARGETTRANSACTIONINTERFACEREGISTERS_RX_DESC_FIFO_SIZE_5_TX_DESC_FIFO_SIZE_5_RX_FIFO_SIZE_5_TX_FIFO_SIZE_5_IBI_FIFO_SIZE_5__INTERRUPT_STATUS__RX_DESC_STAT_bm 0x1
#define TARGETTRANSACTIONINTERFACEREGISTERS_RX_DESC_FIFO_SIZE_5_TX_DESC_FIFO_SIZE_5_RX_FIFO_SIZE_5_TX_FIFO_SIZE_5_IBI_FIFO_SIZE_5__INTERRUPT_STATUS__RX_DESC_STAT_bp 0
#define TARGETTRANSACTIONINTERFACEREGISTERS_RX_DESC_FIFO_SIZE_5_TX_DESC_FIFO_SIZE_5_RX_FIFO_SIZE_5_TX_FIFO_SIZE_5_IBI_FIFO_SIZE_5__INTERRUPT_STATUS__RX_DESC_STAT_bw 1
