#define SOCMANAGEMENTINTERFACEREGISTERS__HDR_TIMEOUT_EN_REG__HDR_TIMEOUT_EN_bp 0
#define SOCMANAGEMENTINTERFACEREGISTERS__HDR_TIMEOUT_EN_REG__HDR_TIMEOUT_EN_bw 1
#define SOCMANAGEMENTINTERFACEREGISTERS__HDR_TIMEOUT_EN_REG__HDR_TIMEOUT_EN_reset 0x0

// reg - SoCManagementInterfaceRegisters::T_HDR_TIMEOUT_REG
